(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='northstar-family-v1';
const defaults={household:'Our household',person:'You',modules:{meals:true,shopping:true,chores:true,calendar:true,noticeboard:true},meals:[],recipes:[{"id":1001,"name":"Mild butter chicken","ingredients":"700 g chicken thighs; 1 onion; 3 garlic cloves; 1 tbsp ginger; 25 g butter; 2 tsp mild curry powder; 1 tsp paprika; 400 g passata; 200 ml cream; 300 g rice","servings":"4 servings","prep":"20 min","cook":"30 min","gf":true,"notes":"Contains dairy. Use gluten-free labelled spices and prevent cross-contact.","steps":"1. Cook 300 g rice according to packet instructions.\n2. Dice 700 g chicken thighs and one onion. Mince 3 garlic cloves and 1 tbsp ginger.\n3. Melt 25 g butter in a large pan. Cook onion for 5 minutes, then add garlic, ginger, 2 tsp mild curry powder and 1 tsp paprika; stir for 30 seconds.\n4. Add chicken and cook until the outside is no longer pink.\n5. Stir in 400 g passata and 150 ml water. Simmer gently for 15 minutes, until chicken reaches 75°C.\n6. Stir in 200 ml cream and warm for 2–3 minutes without boiling hard. Serve over rice.","complete":true},{"id":1002,"name":"Chicken satay rice bowls","ingredients":"650 g chicken breast; 300 g rice; 4 tbsp peanut butter; 200 ml coconut milk; 2 tbsp gluten-free tamari; 1 lime; 2 carrots; 1 cucumber; 1 tbsp oil","servings":"4 servings","prep":"15 min","cook":"20 min","gf":true,"notes":"Contains peanuts. Use gluten-free tamari, not ordinary soy sauce.","steps":"1. Cook 300 g rice. Slice 650 g chicken breast into strips.\n2. Mix 4 tbsp smooth peanut butter, 200 ml coconut milk, 2 tbsp gluten-free tamari, juice of 1 lime and 100 ml warm water until smooth.\n3. Cook chicken in 1 tbsp oil over medium-high heat for 6–8 minutes, until fully cooked (75°C).\n4. Pour in the sauce and simmer for 3–4 minutes. Add a splash of water if it thickens too much.\n5. Serve over rice with 2 grated carrots and 1 sliced cucumber.","complete":true},{"id":1003,"name":"Slow-cooker beef stroganoff","ingredients":"800 g beef chuck; 1 onion; 250 g mushrooms; 350 ml gluten-free beef stock; 2 tsp paprika; 1 tbsp tomato paste; 2 tbsp cornflour; 150 g sour cream; 300 g rice or 1 kg potatoes","servings":"4 servings","prep":"15 min","cook":"6–8 hr LOW","gf":true,"notes":"Use gluten-free stock and cornflour. Add sour cream at the end.","steps":"1. Slice 800 g beef chuck into strips or chunks. Slice 1 onion and 250 g mushrooms.\n2. Put beef, onion, mushrooms, 2 tsp paprika, 1 tbsp tomato paste and 350 ml gluten-free beef stock into the slow cooker.\n3. Cook covered for 7–8 hours on LOW or 4–5 hours on HIGH, until beef is tender.\n4. Mix 2 tbsp cornflour with 3 tbsp cold water. Stir into the slow cooker and cook 15 minutes more.\n5. Turn off the heat and stir through 150 g sour cream. Season to taste. Serve with rice or mashed potatoes.","complete":true},{"id":1004,"name":"Lemon herb roast chicken","ingredients":"1 whole chicken (1.5–1.8 kg); 1 kg potatoes; 500 g carrots; 1 lemon; 3 garlic cloves; 1 tbsp olive oil; rosemary; salt and pepper","servings":"4 servings","prep":"20 min","cook":"75–100 min","gf":true,"notes":"Check chicken is cooked through; use a thermometer at the thickest part (75°C).","steps":"1. Heat oven to 200°C (180°C fan). Pat dry a 1.5–1.8 kg whole chicken.\n2. Cut 1 kg potatoes and 500 g carrots into chunks; toss with 1 tbsp oil and place in a roasting tray.\n3. Rub chicken with 1 tbsp oil, zest and juice of 1 lemon, 3 crushed garlic cloves, rosemary, salt and pepper. Put lemon halves in the cavity if desired.\n4. Place chicken breast-side up over or beside vegetables. Roast for about 20 minutes per 500 g plus 20 minutes, checking the thickest part reaches 75°C.\n5. Rest for 15 minutes before carving. Turn vegetables once during cooking.","complete":true},{"id":1005,"name":"Chicken fried rice","ingredients":"400 g chicken; 600–700 g cooked cold rice; 2 eggs; 1 carrot; 150 g peas; 3 spring onions; 2 tbsp gluten-free tamari; 1 tbsp oil","servings":"4 servings","prep":"15 min","cook":"15 min","gf":true,"notes":"Use rice cooled promptly and refrigerated; reheat until steaming hot.","steps":"1. Use 600–700 g cold cooked rice prepared earlier and refrigerated promptly. Dice 400 g chicken, 1 carrot and 3 spring onions.\n2. Heat 1 tbsp oil in a large wok or pan. Cook chicken for 5–7 minutes until 75°C; transfer to a plate.\n3. Add carrot and 150 g peas; stir-fry 3 minutes. Push aside and scramble 2 beaten eggs.\n4. Add rice, chicken and 2 tbsp gluten-free tamari. Stir-fry until rice is steaming hot throughout.\n5. Stir through spring onion and serve immediately.","complete":true},{"id":1006,"name":"Creamy garlic chicken pasta","ingredients":"600 g chicken breast; 350 g gluten-free pasta; 250 ml cream; 3 garlic cloves; 60 g parmesan; 100 g baby spinach; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"20 min","gf":true,"notes":"Use gluten-free pasta and check stock/cheese labels. Contains dairy.","steps":"1. Cook 350 g gluten-free pasta following the packet; reserve 100 ml pasta water.\n2. Slice 600 g chicken breast. Cook in 1 tbsp oil in a large pan for 6–8 minutes until 75°C; set aside.\n3. Add 3 minced garlic cloves and cook for 30 seconds. Add 250 ml cream and 60 g grated parmesan; simmer gently for 3 minutes.\n4. Add 100 g baby spinach and stir until wilted. Return chicken to pan.\n5. Toss through drained pasta, loosening with pasta water as needed. Season and serve.","complete":true},{"id":1007,"name":"Beef nacho rice bowls","ingredients":"600 g beef mince; 300 g rice; 1 onion; 1 can kidney beans (400 g); 400 g chopped tomatoes; 1 small lettuce; 100 g cheese; 1 avocado; 1 tsp cumin; 1 tsp mild paprika","servings":"4 servings","prep":"15 min","cook":"20 min","gf":true,"notes":"Check seasoning, beans and salsa labels for gluten.","steps":"1. Cook 300 g rice. Dice 1 onion and shred 1 small lettuce.\n2. Brown 600 g beef mince with onion in a large pan for 7–9 minutes, breaking up lumps. Drain excess fat if needed.\n3. Stir in 1 tsp cumin, 1 tsp mild paprika, 400 g chopped tomatoes and a drained 400 g can kidney beans. Simmer 10 minutes until hot and mince is cooked.\n4. Divide rice into bowls. Top with beef mixture, lettuce, 100 g grated cheese and 1 sliced avocado. Add gluten-free salsa if desired.","complete":true},{"id":1008,"name":"Mild coconut chicken curry","ingredients":"650 g chicken; 300 g rice; 1 onion; 2 carrots; 400 ml coconut milk; 2 tsp mild curry powder; 1 tbsp oil; 150 ml water","servings":"4 servings","prep":"15 min","cook":"25 min","gf":true,"notes":"Check curry powder and stock are gluten-free.","steps":"1. Cook 300 g rice. Dice 650 g chicken and 1 onion; slice 2 carrots.\n2. Heat 1 tbsp oil in a deep pan. Cook onion for 4 minutes, then stir in 2 tsp mild curry powder for 30 seconds.\n3. Add chicken and cook until the outside is sealed. Add carrots, 400 ml coconut milk and 150 ml water.\n4. Simmer uncovered for 15–18 minutes, stirring occasionally, until chicken reaches 75°C and carrots are tender.\n5. Taste, season lightly and serve with rice.","complete":true},{"id":1009,"name":"Sausages and creamy mash","ingredients":"8 gluten-free sausages; 1.2 kg potatoes; 40 g butter; 100 ml milk; 300 g peas; 400 ml gluten-free gravy; salt and pepper","servings":"4 servings","prep":"15 min","cook":"25 min","gf":true,"notes":"Sausages and gravy must be labelled gluten-free. Contains dairy.","steps":"1. Peel and chop 1.2 kg potatoes. Boil in salted water for 15–20 minutes until tender.\n2. Meanwhile, cook 8 gluten-free sausages according to packet directions, turning regularly until piping hot throughout.\n3. Drain potatoes well. Mash with 40 g butter and 100 ml warm milk; add more milk if needed.\n4. Cook 300 g peas. Make 400 ml gravy using a gluten-free gravy mix.\n5. Serve two sausages per person with mash, peas and gravy.","complete":true},{"id":1010,"name":"Honey tamari salmon bowls","ingredients":"4 salmon portions (about 600 g total); 300 g rice; 2 broccoli heads; 2 tbsp honey; 2 tbsp gluten-free tamari; 1 lemon; 1 garlic clove; sesame seeds optional","servings":"4 servings","prep":"10 min","cook":"20 min","gf":true,"notes":"Fish and sesame are allergens. Use gluten-free tamari.","steps":"1. Heat oven to 200°C (180°C fan). Cook 300 g rice. Cut 2 broccoli heads into florets.\n2. Mix 2 tbsp honey, 2 tbsp gluten-free tamari, 1 tbsp lemon juice and 1 minced garlic clove.\n3. Put four salmon portions (about 150 g each) on a lined tray and brush with half the sauce. Bake 12–15 minutes, until opaque and easily flaked.\n4. Steam broccoli for 5–7 minutes until tender. Warm remaining sauce in a small pan until bubbling briefly.\n5. Serve salmon with rice and broccoli; drizzle with sauce and sprinkle with sesame seeds if tolerated.","complete":true},{"id":1011,"name":"Tuna cheese baked potatoes","ingredients":"4 large baking potatoes; 2 cans tuna (about 370 g drained total); 120 g grated cheese; 4 tbsp plain yoghurt or mayonnaise; 2 spring onions; 1 tsp oil","servings":"4 servings","prep":"10 min","cook":"50–65 min","gf":true,"notes":"Check mayonnaise and tuna flavouring labels. Contains fish and dairy.","steps":"1. Heat oven to 200°C (180°C fan). Scrub 4 large baking potatoes, prick several times and rub lightly with oil.\n2. Bake directly on a tray for 50–65 minutes, turning once, until soft in the centre.\n3. Drain 2 cans tuna (about 185 g each). Mix with 4 tbsp plain yoghurt or mayonnaise, 2 sliced spring onions and black pepper.\n4. Split potatoes, fluff the centres with a fork and divide tuna mixture between them.\n5. Top with 120 g grated cheese and return to oven for 5 minutes to melt.","complete":true},{"id":1012,"name":"Beef mince tomato pasta","ingredients":"600 g beef mince; 350 g gluten-free pasta; 500 g passata; 1 onion; 2 garlic cloves; 1 tsp dried oregano; 80 g grated cheese; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"25 min","gf":true,"notes":"Use gluten-free pasta and check passata/seasoning labels.","steps":"1. Cook 350 g gluten-free pasta according to packet instructions.\n2. Dice 1 onion and mince 2 garlic cloves. Heat 1 tbsp oil in a pan and cook onion for 4 minutes.\n3. Add 600 g beef mince and cook for 7–9 minutes, breaking up lumps until browned.\n4. Stir in garlic, 500 g passata, 1 tsp dried oregano and 100 ml water. Simmer for 10 minutes; ensure mince is thoroughly cooked.\n5. Toss sauce with drained pasta and serve with 80 g grated cheese.","complete":true},{"id":1013,"name":"Chicken quesadilla plates","ingredients":"500 g chicken breast; 8 small gluten-free corn tortillas; 160 g grated cheese; 1 capsicum; 1 avocado; 1 tsp paprika; 1 tsp cumin; mild gluten-free salsa; 1 tbsp oil","servings":"4 servings","prep":"15 min","cook":"15 min","gf":true,"notes":"Choose tortillas explicitly labelled gluten-free; check salsa.","steps":"1. Slice 500 g chicken and 1 capsicum. Season with 1 tsp paprika and a pinch of cumin.\n2. Cook chicken in 1 tbsp oil over medium-high heat for 6–8 minutes until 75°C; add capsicum and cook 3 minutes.\n3. Divide 160 g grated cheese and chicken mixture over 8 small gluten-free tortillas; fold in half.\n4. Toast quesadillas in a dry pan for 2–3 minutes per side until crisp and cheese melts. Cook in batches.\n5. Serve with 1 diced avocado and mild salsa.","complete":true},{"id":1014,"name":"Slow-cooker pulled pork","ingredients":"1.5 kg pork shoulder; 2 onions; 100 ml apple cider vinegar; 100 ml water; 2 tbsp brown sugar; 1 tbsp smoked paprika; 2 tsp garlic powder; salt and pepper","servings":"6 servings","prep":"15 min","cook":"8 hr LOW","gf":true,"notes":"Check spice rub and sauce labels; use gluten-free cider vinegar.","steps":"1. Slice 2 onions and place in the base of the slow cooker.\n2. Mix 1 tbsp smoked paprika, 2 tsp garlic powder, 1 tsp salt, 2 tbsp brown sugar and black pepper. Rub over a 1.5 kg pork shoulder.\n3. Place pork on onions. Add 100 ml apple cider vinegar and 100 ml water.\n4. Cover and cook 8–9 hours on LOW or 5–6 hours on HIGH, until very tender and safely cooked.\n5. Lift pork out, remove bones and excess fat, then shred with two forks. Mix with some cooking juices. Serve with rice, potatoes or gluten-free rolls.","complete":true},{"id":1015,"name":"Savoury beef mince and rice","ingredients":"600 g beef mince; 300 g rice; 1 onion; 2 carrots; 150 g peas; 250 ml gluten-free beef stock; 1 tbsp tomato paste; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"25 min","gf":true,"notes":"Choose gluten-free stock.","steps":"1. Cook 300 g rice. Dice 1 onion and 2 carrots.\n2. Heat 1 tbsp oil in a pan and cook onion and carrots for 5 minutes.\n3. Add 600 g beef mince and cook 7–9 minutes until browned and cooked through.\n4. Stir in 250 ml gluten-free beef stock, 150 g peas and 1 tbsp tomato paste. Simmer 8–10 minutes until vegetables soften and liquid reduces.\n5. Taste, season and serve over rice.","complete":true},{"id":1016,"name":"Baked chicken drumsticks","ingredients":"8 chicken drumsticks; 800 g potatoes; 3 carrots; 2 tbsp olive oil; 2 tsp paprika; 1 tsp garlic powder; salt and pepper","servings":"4 servings","prep":"15 min","cook":"45–55 min","gf":true,"notes":"Chicken must reach 75°C at the thickest part, away from bone.","steps":"1. Heat oven to 200°C (180°C fan). Line a large roasting tray.\n2. Cut 800 g potatoes and 3 carrots into chunks. Toss with 1 tbsp oil, salt and pepper.\n3. Toss 8 chicken drumsticks with 1 tbsp oil, 2 tsp paprika and 1 tsp garlic powder. Check spices are gluten-free.\n4. Arrange chicken and vegetables in a single layer. Roast 45–55 minutes, turning halfway.\n5. Check the thickest part of each drumstick reaches 75°C; cook longer if needed.","complete":true},{"id":1017,"name":"Egg and vegetable rice bowls","ingredients":"4 eggs; 300 g rice; 1 carrot; 150 g peas; 3 spring onions; 2 tbsp gluten-free tamari; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"15 min","gf":true,"notes":"Use gluten-free tamari.","steps":"1. Cook 300 g rice or use freshly cooked rice. Dice 1 carrot and slice 3 spring onions.\n2. Heat 1 tbsp oil in a large pan. Cook carrot and 150 g peas for 4 minutes.\n3. Push vegetables to one side. Scramble 4 beaten eggs until just set.\n4. Add rice and 2 tbsp gluten-free tamari. Stir-fry until everything is piping hot.\n5. Stir through spring onion and serve.","complete":true},{"id":1018,"name":"Creamy tomato chicken rice","ingredients":"650 g chicken; 300 g rice; 400 g passata; 150 ml cream; 1 onion; 2 garlic cloves; 1 tsp Italian herbs; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"30 min","gf":true,"notes":"Check herbs and passata labels. Contains dairy.","steps":"1. Cook 300 g rice. Dice 650 g chicken and 1 onion; mince 2 garlic cloves.\n2. Heat 1 tbsp oil in a deep pan. Cook onion for 4 minutes, add garlic for 30 seconds.\n3. Add chicken and cook, stirring, until the outside is sealed. Stir in 400 g passata, 1 tsp Italian herbs and 100 ml water.\n4. Simmer for 15 minutes, stirring occasionally, until chicken reaches 75°C. Stir in 150 ml cream and warm for 2 minutes.\n5. Serve the creamy tomato chicken over rice.","complete":true},{"id":1019,"name":"Chicken potato tray bake","ingredients":"700 g chicken thighs; 800 g potatoes; 3 carrots; 1 onion; 1 lemon; 2 tsp oregano; 2 tbsp olive oil; 1 tsp paprika","servings":"4 servings","prep":"15 min","cook":"45–55 min","gf":true,"notes":"Check seasoning labels and cook chicken to 75°C.","steps":"1. Heat oven to 200°C (180°C fan). Cut 800 g potatoes, 3 carrots and 1 onion into chunks.\n2. Toss vegetables with 1 tbsp oil, juice of 1 lemon, 2 tsp oregano, salt and pepper. Spread on a roasting tray.\n3. Add 700 g chicken thighs and rub with another 1 tbsp oil and 1 tsp paprika.\n4. Roast 45–55 minutes, turning vegetables halfway, until potatoes are tender and chicken reaches 75°C.\n5. Rest chicken for 5 minutes before serving.","complete":true},{"id":1020,"name":"Mild beef and bean chilli","ingredients":"600 g beef mince; 300 g rice; 1 onion; 1 capsicum; 1 can kidney beans (400 g); 400 g chopped tomatoes; 1 tsp mild paprika; 1 tsp cumin; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"30 min","gf":true,"notes":"Check canned ingredients and spice labels. Mild, not hot.","steps":"1. Cook 300 g rice. Dice 1 onion and 1 capsicum.\n2. Heat 1 tbsp oil in a pan; cook onion and capsicum for 5 minutes. Add 600 g beef mince and brown for 7–9 minutes.\n3. Stir in 400 g chopped tomatoes, 1 drained 400 g can kidney beans, 1 tsp mild paprika, 1 tsp cumin and 100 ml water.\n4. Simmer gently for 15 minutes, stirring occasionally, until thick and mince is fully cooked. Add a splash of water if needed.\n5. Serve over rice with grated cheese or plain yoghurt if desired.","complete":true},{"id":1021,"name":"Coconut chickpea curry","ingredients":"2 cans chickpeas (400 g each); 400 ml coconut milk; 400 g chopped tomatoes; 1 onion; 100 g spinach; 300 g rice; 2 tsp mild curry powder; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"20 min","gf":true,"notes":"Vegetarian; check curry powder and canned labels.","steps":"1. Cook 300 g rice. Dice 1 onion. Drain and rinse two 400 g cans chickpeas.\n2. Heat 1 tbsp oil in a pan and cook onion for 5 minutes. Add 2 tsp mild curry powder and stir for 30 seconds.\n3. Add chickpeas, 400 g chopped tomatoes and 400 ml coconut milk. Simmer for 12 minutes.\n4. Stir in 100 g spinach and cook until wilted. Add salt and a squeeze of lemon to taste.\n5. Serve with rice.","complete":true},{"id":1022,"name":"Lentil and vegetable soup","ingredients":"250 g red lentils; 2 carrots; 2 potatoes; 1 onion; 2 garlic cloves; 1 litre gluten-free vegetable stock; 400 g chopped tomatoes; 1 tsp cumin; 1 tbsp oil","servings":"4 servings","prep":"15 min","cook":"30 min","gf":true,"notes":"Choose gluten-free vegetable stock. Vegetarian and dairy-free.","steps":"1. Dice 1 onion, 2 carrots and 2 potatoes. Rinse 250 g red lentils.\n2. Heat 1 tbsp oil in a large pot. Cook onion and carrots for 5 minutes; add 2 minced garlic cloves for 30 seconds.\n3. Add lentils, potatoes, 1 litre gluten-free vegetable stock, 1 tsp cumin and 400 g chopped tomatoes.\n4. Bring to a boil, then simmer uncovered for 20–25 minutes, stirring occasionally, until lentils and potatoes are soft. Add water if too thick.\n5. Season to taste and serve with gluten-free bread if wanted.","complete":true},{"id":1023,"name":"Tuna sweetcorn-free pasta bake","ingredients":"2 cans tuna (about 370 g drained); 300 g gluten-free pasta; 400 g passata; 100 g plain yoghurt; 100 g spinach; 150 g grated cheese","servings":"4 servings","prep":"15 min","cook":"25 min","gf":true,"notes":"No corn included. Use gluten-free pasta and check all labels.","steps":"1. Heat oven to 190°C (170°C fan). Cook 300 g gluten-free pasta 2 minutes less than packet directions; drain.\n2. Mix 2 drained cans tuna, 400 g passata, 100 g plain yoghurt, 100 g spinach and half of 150 g grated cheese.\n3. Fold through pasta and spoon into a baking dish. Add a splash of pasta water if dry.\n4. Sprinkle remaining cheese over the top. Bake for 20–25 minutes until bubbling and hot throughout.\n5. Rest for 5 minutes before serving.","complete":true},{"id":1024,"name":"Beef and potato cottage pie","ingredients":"600 g beef mince; 900 g potatoes; 1 onion; 2 carrots; 150 g peas; 300 ml gluten-free beef stock; 1 tbsp tomato paste; 30 g butter; 80 ml milk","servings":"4 servings","prep":"20 min","cook":"40 min","gf":true,"notes":"Use gluten-free stock and cornflour if thickening. Contains dairy if using butter/milk.","steps":"1. Heat oven to 200°C (180°C fan). Peel and chop 900 g potatoes; boil 15–20 minutes until tender.\n2. Meanwhile, dice 1 onion and 2 carrots. Brown 600 g beef mince in a pan, then add vegetables and cook 5 minutes.\n3. Stir in 300 ml gluten-free beef stock, 1 tbsp tomato paste and 150 g peas. Simmer 8 minutes until slightly thickened.\n4. Mash drained potatoes with 30 g butter and 80 ml milk. Put mince mixture in a baking dish and spread mash over it.\n5. Bake 20–25 minutes until the top is lightly golden and filling bubbles.","complete":true},{"id":1025,"name":"Garlic butter hoki with potatoes","ingredients":"4 hoki fillets (600–700 g); 800 g potatoes; 300 g green beans; 40 g butter; 2 garlic cloves; ½ lemon; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"25 min","gf":true,"notes":"Contains fish and dairy. Check any seasoning blend.","steps":"1. Heat oven to 200°C (180°C fan). Cut 800 g potatoes into chunks and boil 15–20 minutes until tender.\n2. Put 4 hoki fillets (about 150–180 g each) in a lightly oiled baking dish.\n3. Melt 40 g butter with 2 minced garlic cloves and juice of half a lemon. Spoon over fish.\n4. Bake 12–15 minutes, until fish is opaque and flakes easily. Steam 300 g green beans for 5–6 minutes.\n5. Serve fish with potatoes and beans; spoon over any buttery juices.","complete":true},{"id":1026,"name":"Pork and vegetable rice bowls","ingredients":"600 g pork strips; 300 g rice; 2 carrots; 250 g cabbage; 2 tbsp gluten-free tamari; 1 tbsp honey; 1 garlic clove; 1 tbsp oil","servings":"4 servings","prep":"15 min","cook":"15 min","gf":true,"notes":"Use gluten-free tamari and check marinades.","steps":"1. Cook 300 g rice. Thinly slice 600 g pork, 2 carrots and 250 g cabbage.\n2. Mix 2 tbsp gluten-free tamari, 1 tbsp honey, 1 minced garlic clove and 2 tbsp water.\n3. Heat 1 tbsp oil in a wok or large pan. Stir-fry pork in batches for 3–5 minutes until cooked through.\n4. Add carrots and cabbage; stir-fry 4 minutes. Return pork and add sauce; cook until bubbling and pork reaches a safe temperature.\n5. Serve over rice.","complete":true},{"id":1027,"name":"Mild red lentil dhal","ingredients":"250 g red lentils; 300 g rice; 1 onion; 2 garlic cloves; 1 tbsp ginger; 400 ml coconut milk; 2 tsp mild curry powder; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"25 min","gf":true,"notes":"Vegetarian; check spice labels.","steps":"1. Cook 300 g rice. Dice 1 onion; mince 2 garlic cloves and 1 tbsp ginger. Rinse 250 g red lentils.\n2. Heat 1 tbsp oil in a pot and cook onion for 5 minutes. Add garlic, ginger and 2 tsp mild curry powder; stir for 30 seconds.\n3. Add lentils, 400 ml coconut milk and 500 ml water. Bring to a boil.\n4. Reduce to a simmer and cook 18–22 minutes, stirring often, until lentils are soft. Add water if needed.\n5. Season lightly and serve with rice.","complete":true},{"id":1028,"name":"Baked meatballs in tomato sauce","ingredients":"600 g beef mince; 1 egg; 40 g gluten-free breadcrumbs; 500 g passata; 2 garlic cloves; 1 tsp oregano; 300 g rice or gluten-free pasta","servings":"4 servings","prep":"15 min","cook":"30 min","gf":true,"notes":"Use gluten-free breadcrumbs and check passata.","steps":"1. Heat oven to 200°C (180°C fan). Mix 600 g beef mince, 1 egg, 40 g gluten-free breadcrumbs, 1 tsp oregano and a pinch of salt.\n2. Roll into about 16 meatballs and place on a lined tray. Bake 12 minutes.\n3. Meanwhile, warm 500 g passata with 2 minced garlic cloves and 1 tsp dried basil in a wide pan.\n4. Transfer meatballs into sauce and simmer gently for 10–12 minutes, until cooked through.\n5. Serve with 300 g cooked rice or gluten-free pasta.","complete":true},{"id":1029,"name":"Banana oat pancakes","ingredients":"2 ripe bananas; 3 eggs; 150 g rolled oats; 150 ml milk; 1 tsp gluten-free baking powder; ½ tsp cinnamon; a little oil for pan","servings":"4 servings","prep":"10 min","cook":"15 min","gf":true,"notes":"Use certified gluten-free oats if required for coeliac disease; contains egg and dairy.","steps":"1. Mash 2 ripe bananas in a bowl. Whisk in 3 eggs and 150 ml milk.\n2. Stir in 150 g rolled oats, 1 tsp gluten-free baking powder and ½ tsp cinnamon. Rest 5 minutes.\n3. Heat a lightly oiled non-stick pan over medium-low heat. Add small ladlefuls of batter.\n4. Cook 2–3 minutes until bubbles appear and edges set; flip and cook another 1–2 minutes.\n5. Serve with fruit or yoghurt. Make smaller pancakes so they flip easily.","complete":true},{"id":1030,"name":"Creamy mushroom rice","ingredients":"300 g rice; 300 g mushrooms; 1 onion; 2 garlic cloves; 750 ml gluten-free vegetable stock; 100 ml cream; 50 g parmesan; 80 g spinach; 20 g butter; 1 tbsp oil","servings":"4 servings","prep":"10 min","cook":"30 min","gf":true,"notes":"Vegetarian; use gluten-free stock. Contains dairy.","steps":"1. Dice 1 onion, mince 2 garlic cloves and slice 300 g mushrooms. Rinse 300 g rice.\n2. Heat 1 tbsp oil and 20 g butter in a deep pan. Cook onion and mushrooms for 6 minutes; add garlic for 30 seconds.\n3. Stir in rice, then add 750 ml hot gluten-free vegetable stock in 3 additions, stirring regularly and allowing liquid to absorb between additions.\n4. Cook 20–25 minutes until rice is tender; add a little hot water if needed.\n5. Stir in 100 ml cream, 50 g parmesan and 80 g spinach. Rest 2 minutes and serve.","complete":true},{"id":1031,"name":"Slow-cooker chicken and potato stew","ingredients":"700 g chicken thighs; 700 g potatoes; 3 carrots; 1 onion; 500 ml gluten-free chicken stock; 1 tsp thyme; 1 tbsp cornflour optional","servings":"4 servings","prep":"15 min","cook":"6 hr LOW","gf":true,"notes":"Choose gluten-free stock; check chicken reaches 75°C.","steps":"1. Chop 700 g chicken thighs, 700 g potatoes, 3 carrots and 1 onion.\n2. Put everything in the slow cooker with 500 ml gluten-free chicken stock, 1 tsp thyme, 1 bay leaf and black pepper.\n3. Cover and cook 6–7 hours on LOW or 3–4 hours on HIGH, until vegetables are tender and chicken reaches 75°C.\n4. For a thicker stew, mix 1 tbsp cornflour with 2 tbsp cold water, stir in and cook 15 minutes more.\n5. Remove bay leaf, season and serve.","complete":true},{"id":1032,"name":"Cheesy broccoli potato bake","ingredients":"800 g potatoes; 1 large broccoli; 450 ml milk; 30 g butter; 2 tbsp gluten-free cornflour; 200 g cheddar cheese","servings":"4 servings","prep":"15 min","cook":"45 min","gf":true,"notes":"Vegetarian; use gluten-free cornflour. Contains dairy.","steps":"1. Heat oven to 190°C (170°C fan). Slice 800 g potatoes thinly and cut 1 large broccoli into florets.\n2. Parboil potatoes for 8 minutes; add broccoli for the final 3 minutes. Drain.\n3. Melt 30 g butter in a saucepan. Whisk in 2 tbsp cornflour, then gradually whisk in 400 ml milk until smooth and thickened. Stir in 150 g grated cheddar.\n4. Layer potatoes and broccoli in a baking dish and pour over cheese sauce. Top with another 50 g cheese.\n5. Bake 25–30 minutes until golden and bubbling, and potatoes are tender.","complete":true},{"id":1033,"name":"Chicken and pumpkin coconut soup","ingredients":"500 g chicken; 700 g pumpkin; 1 onion; 1 carrot; 750 ml gluten-free chicken stock; 200 ml coconut milk; 1 tbsp oil","servings":"4 servings","prep":"15 min","cook":"30 min","gf":true,"notes":"Use gluten-free stock. Dairy-free if no dairy toppings added.","steps":"1. Dice 500 g chicken, 700 g pumpkin, 1 onion and 1 carrot.\n2. Heat 1 tbsp oil in a large pot. Cook onion for 4 minutes, then add chicken and cook until the outside is sealed.\n3. Add pumpkin, carrot, 750 ml gluten-free chicken stock and 200 ml coconut milk. Bring to a boil, then simmer 20 minutes until vegetables are soft and chicken reaches 75°C.\n4. Remove about half the vegetables and blend the soup carefully until smooth, or blend all for a creamy texture. Return chunks if reserved.\n5. Season and serve with gluten-free toast if desired.","complete":true},{"id":1034,"name":"Lemon chicken and rice soup","ingredients":"500 g chicken; 150 g rice; 2 carrots; 2 celery sticks; 1 onion; 1.2 litres gluten-free chicken stock; 1 lemon; 1 tbsp oil","servings":"4 servings","prep":"15 min","cook":"35 min","gf":true,"notes":"Choose gluten-free stock.","steps":"1. Dice 500 g chicken, 2 carrots, 2 celery sticks and 1 onion.\n2. Heat 1 tbsp oil in a pot and cook onion, carrot and celery for 5 minutes. Add chicken and stir for 3 minutes.\n3. Add 1.2 litres gluten-free chicken stock and 150 g rinsed rice. Bring to a boil.\n4. Simmer 20–25 minutes, stirring occasionally, until rice is tender and chicken reaches 75°C. Add hot water if soup becomes too thick.\n5. Stir in juice of 1 lemon, season and serve.","complete":true},{"id":1035,"name":"Baked apples with cinnamon oats","ingredients":"4 apples; 60 g rolled oats; 25 g butter; 2 tbsp brown sugar; ½ tsp cinnamon; 100 ml water; plain yoghurt optional","servings":"4 servings","prep":"10 min","cook":"25 min","gf":true,"notes":"Use certified gluten-free oats if required; contains dairy if using butter/yoghurt.","steps":"1. Heat oven to 180°C (160°C fan). Core 4 apples, leaving the base intact, and place in a small baking dish.\n2. Mix 60 g rolled oats, 25 g softened butter, 2 tbsp brown sugar and ½ tsp cinnamon.\n3. Spoon oat mixture into apple centres. Pour 100 ml water into the bottom of the dish.\n4. Bake 25–35 minutes until apples are tender when pierced. Cover loosely with foil if topping browns too quickly.\n5. Serve warm with plain yoghurt if desired.","complete":true}],shopping:[],chores:[],events:[],notices:[]};

let data;try{data={...defaults,...JSON.parse(localStorage.getItem(KEY)||'{}')};data.modules={...defaults.modules,...(data.modules||{})}; if(!Array.isArray(data.recipes)||!data.recipes.some(r=>r.complete)){const previous=Array.isArray(data.recipes)?data.recipes:[];const custom=previous.filter(r=>r&&r.name&&Number(r.id)>300&&!defaults.recipes.some(n=>n.name===r.name));data.recipes=[...defaults.recipes,...custom]}}catch{data=structuredClone(defaults)}
let tab='home', recipeSearch='', recipeCategory='all', recipeLimit=60;const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(data));$('#save-status').textContent='Saved on this device';window.dispatchEvent(new CustomEvent('northstar:local-state',{detail:{household:data.household,meals:data.meals,shopping:data.shopping,chores:data.chores,events:data.events,notices:data.notices}}))}catch{$('#save-status').textContent='Could not save — storage may be unavailable'}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Date.now()+Math.floor(Math.random()*1000);const dateToday=()=>new Date().toISOString().slice(0,10);
function shell(){document.title='Northstar Family Edition';$('#app').innerHTML=`<header class="top"><div class="brand"><div class="logo">N</div><div><div class="eyebrow">Northstar</div><h1>Family Edition</h1><div class="muted tiny">A calmer home, together.</div></div></div><div><span class="pill">Family Edition</span><div id="save-status" class="tiny muted">Saved on this device</div></div></header><nav class="nav">${[['home','Home'],['meals','Meals & recipes'],['shopping','Shopping'],['chores','Chores'],['calendar','Calendar'],['noticeboard','Noticeboard'],['settings','Settings']].map(([id,n])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${n}</button>`).join('')}</nav><div class="tool-picker"><label for="tool-select">Jump to a tool</label><select id="tool-select"><option value="home">Home dashboard</option><option value="meals">Meals & recipe library</option><option value="shopping">Shopping list</option><option value="chores">Chores & cleaning</option><option value="calendar">Calendar & events</option><option value="noticeboard">Household noticeboard</option><option value="settings">Settings & backups</option></select></div><main id="view"></main><footer>Northstar Family Edition · Local-first household planner. Optional authenticated cloud sharing must be configured in Settings.</footer>`;$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#tool-select').onchange=e=>{tab=e.target.value;render()};render()}
function list(items,fn,empty){return items.length?items.map(fn).join(''):`<div class="empty">${empty}</div>`}
function item(title,sub='',right=''){return `<div class="item"><div><strong>${esc(title)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</div>${right}</div>`}
function render(){if(!$('#view'))return;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if($('#tool-select'))$('#tool-select').value=tab;const v=$('#view');if(tab!=='home'&&!data.modules[tab]&&['meals','shopping','chores','calendar','noticeboard'].includes(tab)){v.innerHTML=`<section class="panel"><h2>Module is turned off</h2><p class="muted">Enable it in Settings to use this area.</p><button data-go-settings>Open settings</button></section>`; $('[data-go-settings]').onclick=()=>{tab='settings';render()};return}
if(tab==='home'){v.innerHTML=`<section class="hero"><div class="eyebrow">Your household hub</div><h2>Welcome to ${esc(data.household||'your household')}</h2><p class="muted">Plan meals, keep the shopping list together and make household jobs easier to see.</p><div class="stats"><div class="stat"><strong>${data.meals.length}</strong><span class="tiny">Planned meals</span></div><div class="stat"><strong>${data.shopping.filter(x=>!x.done).length}</strong><span class="tiny">Shopping items</span></div><div class="stat"><strong>${data.chores.filter(x=>!x.done).length}</strong><span class="tiny">Open chores</span></div></div></section><div class="grid"><section class="panel"><h2>This week's meals</h2>${list(data.meals,m=>item(m.day+' · '+m.meal,m.recipe), 'No meals planned yet.')}<button data-jump="meals">Plan meals</button></section><section class="panel"><h2>Shopping list</h2>${list(data.shopping.filter(x=>!x.done).slice(0,5),x=>item(x.name,x.qty), 'Your list is clear.')}<button data-jump="shopping">Open shopping list</button></section><section class="panel"><h2>Chores</h2>${list(data.chores.filter(x=>!x.done).slice(0,4),x=>item(x.title,x.person||'Unassigned'), 'Nothing outstanding.')}<button data-jump="chores">Manage chores</button></section><section class="panel"><h2>Household notes</h2>${list(data.notices.slice(0,3),x=>item(x.title,x.body), 'No notices yet.')}<button data-jump="noticeboard">Open noticeboard</button></section></div>`;$$('[data-jump]').forEach(b=>b.onclick=()=>{tab=b.dataset.jump;render()});return}
if(tab==='meals'){v.innerHTML=`<div class="grid"><section class="panel"><h2>Weekly meal planner</h2><form id="meal-form" class="stack"><label>Day</label><select name="day">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<option>${d}</option>`).join('')}</select><label>Meal</label><input name="meal" placeholder="e.g. Dinner" value="Dinner" required><label>Recipe</label><select name="recipe">${data.recipes.map(r=>`<option>${esc(r.name)}</option>`).join('')}</select><button class="primary">Add to plan</button></form><h3 style="margin-top:22px">Planned meals</h3>${list(data.meals,(m,i)=>item(m.day+' · '+m.meal,m.recipe,`<button data-remove-meal="${i}">Remove</button>`),'No meals planned yet.')}</section><section class="panel"><h2>Complete recipe collection <span class="pill">${data.recipes.length} recipes</span></h2><div class="recipe-tools"><input id="recipe-search" type="search" placeholder="Search meals or ingredients…" value="${esc(recipeSearch)}"><select id="recipe-category"><option value="all">All meal ideas</option><option value="chicken">Chicken</option><option value="beef">Beef</option><option value="pork">Pork</option><option value="lamb">Lamb</option><option value="fish">Fish & seafood</option><option value="vegetarian">Vegetarian</option><option value="breakfast">Breakfast</option><option value="lunch">Lunch</option></select></div><p class="muted tiny">Always check packaging and cross-contact warnings. Labels here are reminders, not a guarantee of safety.</p><div class="recipe-grid">${data.recipes.filter(r=>{const q=recipeSearch.toLowerCase();const c=recipeCategory;return (!q||(r.name+" "+r.ingredients).toLowerCase().includes(q))&&(c==="all"||r.name.toLowerCase().includes(c)||(c==="vegetarian"&&/lentil|chickpea|vegetable|tofu|bean|mushroom|spinach|halloumi|eggplant|cauliflower/i.test(r.name))||(c==="fish"&&/fish|salmon|hoki|tuna|prawn|seafood/i.test(r.name)));}).slice(0,recipeLimit).map((r)=>{const i=data.recipes.indexOf(r);return `<article class="recipe-card"><h3>${esc(r.name)}</h3><div class="recipe-tags"><span class="tag ${r.gf?'':'caution'}">${r.gf?'GF-friendly ingredients':'Check ingredients'}</span></div><p><strong>${esc(r.servings||'Family recipe')}</strong> · Prep ${esc(r.prep||'—')} · Cook ${esc(r.cook||'—')}</p><p><strong>Ingredients</strong><br>${esc(r.ingredients).replace(/, /g,'<br>')}</p>${r.steps?`<details><summary>Step-by-step method</summary><ol>${r.steps.split('\n').map(step=>`<li>${esc(step.replace(/^\d+\. /,''))}</li>`).join('')}</ol></details>`:''}${r.notes?`<p class="muted tiny">${esc(r.notes)}</p>`:''}<button data-add-ingredients="${i}">Add ingredients to list</button></article>`}).join('')}</div><div class="actions"><button id="show-more-recipes">Show more recipes</button><span class="muted tiny">Showing up to ${recipeLimit} matching recipes.</span></div><hr style="border-color:var(--line);margin:18px 0"><h3>Add a recipe</h3><form id="recipe-form" class="stack"><label>Recipe name</label><input name="name" required placeholder="Recipe name"><label>Ingredients (comma-separated)</label><textarea name="ingredients" required placeholder="Ingredient 1, ingredient 2"></textarea><label>Food notes / allergy reminders</label><input name="notes" placeholder="Check labels, substitutions..."><label class="checks"><input type="checkbox" name="gf"><span>Intended to use gluten-free ingredients</span></label><button class="primary">Save recipe</button></form></section></div>`;
$('#meal-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.meals.push({day:f.get('day'),meal:f.get('meal'),recipe:f.get('recipe')});save();render()};$('#recipe-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.recipes.push({id:uid(),name:f.get('name'),ingredients:f.get('ingredients'),notes:f.get('notes'),gf:f.has('gf')});save();render()};$('#recipe-search').oninput=e=>{recipeSearch=e.target.value;recipeLimit=60;const pos=e.target.selectionStart;render();const el=$('#recipe-search');el.focus();el.setSelectionRange(pos,pos)};$('#recipe-category').value=recipeCategory;$('#recipe-category').onchange=e=>{recipeCategory=e.target.value;recipeLimit=60;render()};$('#show-more-recipes').onclick=()=>{recipeLimit+=60;render()};$$('[data-remove-meal]').forEach(b=>b.onclick=()=>{data.meals.splice(+b.dataset.removeMeal,1);save();render()});$$('[data-add-ingredients]').forEach(b=>b.onclick=()=>{const r=data.recipes[+b.dataset.addIngredients];r.ingredients.split(';').map(x=>x.trim()).filter(Boolean).forEach(name=>{if(!data.shopping.some(s=>s.name.toLowerCase()===name.toLowerCase()&&!s.done))data.shopping.push({id:uid(),name,qty:'',done:false})});save();tab='shopping';render()});return}
if(tab==='shopping'){v.innerHTML=`<div class="grid"><section class="panel"><h2>Shopping list</h2><form id="shop-form" class="stack"><label>Item</label><input name="name" required placeholder="e.g. milk"><label>Quantity / notes</label><input name="qty" placeholder="e.g. 2 litres"><button class="primary">Add item</button></form><div style="margin-top:18px">${list(data.shopping,(x,i)=>`<div class="item"><label class="checks" style="margin:0;flex:1"><input type="checkbox" data-shop-done="${i}" ${x.done?'checked':''}><span style="${x.done?'text-decoration:line-through;opacity:.6':''}"><strong>${esc(x.name)}</strong><small>${esc(x.qty||'')}</small></span></label><button data-shop-remove="${i}">Remove</button></div>`,'No shopping items yet.')}</div><div class="actions"><button id="clear-done">Remove checked items</button><button id="export-list">Copy list text</button></div><p class="muted tiny" id="export-msg"></p></section><section class="panel"><h2>Meal ingredients</h2><p class="muted">Use “Add ingredients” in Meals & recipes to merge recipe ingredients into this list. Similar items are not automatically merged by quantity.</p><button data-jump="meals">Browse recipes</button></section></div>`;$('#shop-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.shopping.push({id:uid(),name:f.get('name'),qty:f.get('qty'),done:false});save();render()};$$('[data-shop-done]').forEach(b=>b.onchange=()=>{data.shopping[+b.dataset.shopDone].done=b.checked;save();render()});$$('[data-shop-remove]').forEach(b=>b.onclick=()=>{data.shopping.splice(+b.dataset.shopRemove,1);save();render()});$('#clear-done').onclick=()=>{data.shopping=data.shopping.filter(x=>!x.done);save();render()};$('#export-list').onclick=()=>{const t=data.shopping.filter(x=>!x.done).map(x=>'- '+x.name+(x.qty?' — '+x.qty:'')).join('\n');navigator.clipboard?.writeText(t).then(()=>$('#export-msg').textContent='List copied.').catch(()=>$('#export-msg').textContent=t||'List is empty.');if(!navigator.clipboard)$('#export-msg').textContent=t||'List is empty.'};$$('[data-jump]').forEach(b=>b.onclick=()=>{tab=b.dataset.jump;render()});return}
if(tab==='chores'){v.innerHTML=`<div class="grid"><section class="panel"><h2>Add a chore</h2><form id="chore-form" class="stack"><label>Chore</label><input name="title" required placeholder="e.g. Empty dishwasher"><div class="formrow"><div><label>Person</label><input name="person" placeholder="Anyone / name"></div><div><label>Due date</label><input type="date" name="due"></div></div><button class="primary">Add chore</button></form></section><section class="panel"><h2>Chore list</h2>${list(data.chores,(x,i)=>`<div class="item"><label class="checks" style="margin:0;flex:1"><input type="checkbox" data-chore-done="${i}" ${x.done?'checked':''}><span><strong>${esc(x.title)}</strong><small>${esc(x.person||'Unassigned')}${x.due?' · Due '+esc(x.due):''}</small></span></label><button data-chore-remove="${i}">Remove</button></div>`,'No chores added yet.')}</section></div>`;$('#chore-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.chores.push({title:f.get('title'),person:f.get('person'),due:f.get('due'),done:false});save();render()};$$('[data-chore-done]').forEach(b=>b.onchange=()=>{data.chores[+b.dataset.choreDone].done=b.checked;save();render()});$$('[data-chore-remove]').forEach(b=>b.onclick=()=>{data.chores.splice(+b.dataset.choreRemove,1);save();render()});return}
if(tab==='calendar'){v.innerHTML=`<div class="grid"><section class="panel"><h2>Add an event</h2><form id="event-form" class="stack"><label>Event</label><input name="title" required placeholder="e.g. Family dinner"><label>Date</label><input type="date" name="date" value="${dateToday()}" required><label>Time / notes</label><input name="notes" placeholder="e.g. 6:30pm"><button class="primary">Add event</button></form></section><section class="panel"><h2>Upcoming events</h2>${list([...data.events].sort((a,b)=>a.date.localeCompare(b.date)),(x,i)=>item(x.title,x.date+' '+(x.notes||''),`<button data-event-remove="${data.events.indexOf(x)}">Remove</button>`),'No events planned.')}</section></div>`;$('#event-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.events.push({title:f.get('title'),date:f.get('date'),notes:f.get('notes')});save();render()};$$('[data-event-remove]').forEach(b=>b.onclick=()=>{data.events.splice(+b.dataset.eventRemove,1);save();render()});return}
if(tab==='noticeboard'){v.innerHTML=`<div class="grid"><section class="panel"><h2>Post a notice</h2><form id="notice-form" class="stack"><label>Title</label><input name="title" required placeholder="Notice title"><label>Message</label><textarea name="body" required placeholder="What should everyone know?"></textarea><button class="primary">Post notice</button></form></section><section class="panel"><h2>Household noticeboard</h2>${list(data.notices,(x,i)=>item(x.title,x.body,`<button data-notice-remove="${i}">Remove</button>`),'No notices yet.')}</section></div>`;$('#notice-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.notices.unshift({title:f.get('title'),body:f.get('body')});save();render()};$$('[data-notice-remove]').forEach(b=>b.onclick=()=>{data.notices.splice(+b.dataset.noticeRemove,1);save();render()});return}
if(tab==='settings'){v.innerHTML=`<div class="grid"><section class="panel"><h2>Household setup</h2><form id="settings-form" class="stack"><label>Household name</label><input name="household" value="${esc(data.household)}" required><label>Your display name (this device)</label><input name="person" value="${esc(data.person)}" required><h3>Choose your modules</h3>${[['meals','Meals & recipes'],['shopping','Shopping list'],['chores','Chores'],['calendar','Calendar'],['noticeboard','Noticeboard']].map(([k,n])=>`<label class="checks"><input type="checkbox" name="mod-${k}" ${data.modules[k]?'checked':''}><span>${n}</span></label>`).join('')}<button class="primary">Save settings</button></form></section><section class="panel"><h2>Family sharing</h2><p class="muted">Secure account-based sharing using Supabase. Requires a Supabase project, configured public keys, deployed database schema and Edge Functions. Keep service-role keys server-side only.</p><div class="warning" id="cloud-warning">Cloud sharing is not configured yet. Follow SUPABASE_SETUP.md, then set supabase-config.js.</div><div class="stack"><label>Email address</label><input id="cloud-email" type="email" autocomplete="email" placeholder="you@example.com"><button type="button" id="cloud-signin" class="primary">Send secure sign-in link</button><button type="button" id="cloud-signout">Sign out</button><p id="cloud-status" class="muted tiny" aria-live="polite">Checking cloud configuration…</p><hr style="border-color:var(--line)"><label>Household name (for a new household)</label><input id="cloud-household-name" value="${esc(data.household)}" maxlength="100"><button type="button" id="cloud-create-household">Create household</button><label>Invitation code</label><input id="cloud-invite-token" autocomplete="off" placeholder="Paste invitation code"><button type="button" id="cloud-join-household">Join invited household</button><button type="button" id="cloud-create-invite">Create invitation (72 hours)</button><textarea id="cloud-invite-output" rows="3" readonly placeholder="Your invitation code and expiry will appear here"></textarea><button type="button" id="cloud-copy-invite">Copy invitation details</button></div><p class="muted tiny">Invitation codes expire after 72 hours by default and can be redeemed once. Share them only with people you trust. Anyone who redeems a valid invitation becomes a household member and can access shared household planning data. Do not put sensitive personal information in shared records.</p><h3 style="margin-top:18px">Data & privacy</h3><p>Household planning data is stored locally and, once cloud sharing is configured, in your Supabase household. Private records are designed to be owner-only. A successful deployment still needs two-account permission tests before real use.</p><h3 style="margin-top:18px">Backup</h3><p class="muted tiny">Export your data to keep a copy, or import a previous Northstar Family Edition JSON backup.</p><div class="stack"><button id="backup-export">Export backup JSON</button><label>Import backup JSON</label><input type="file" id="backup-import" accept="application/json"><button id="reset-data">Reset all local data</button><p id="settings-msg" class="muted tiny"></p></div></div></section></div>`;$('#settings-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.household=f.get('household');data.person=f.get('person');Object.keys(data.modules).forEach(k=>data.modules[k]=f.has('mod-'+k));save();render()};const cloudStatus=$('#cloud-status'), cloudWarning=$('#cloud-warning');const cloudMsg=m=>{if(cloudStatus)cloudStatus.textContent=m};const cloud=()=>window.NorthstarCloud;if(cloud()&&cloud().configured){cloudWarning.textContent='Cloud module loaded. Sign in to create or join a household.';cloudMsg('Cloud module ready.')}window.addEventListener('northstar:cloud-status',e=>{cloudMsg(e.detail.message);if(cloudWarning&&e.detail.message.includes('needs your Supabase'))cloudWarning.textContent=e.detail.message});$('#cloud-signin').onclick=async()=>{try{if(!cloud()?.configured)throw Error('Configure Supabase first; see SUPABASE_SETUP.md.');const email=$('#cloud-email').value.trim();if(!email)throw Error('Enter your email address.');await cloud().signIn(email);cloudMsg('Sign-in link sent. Open it on this device, then return to Settings.')}catch(e){cloudMsg(e.message)}};$('#cloud-signout').onclick=async()=>{try{if(!cloud()?.configured)throw Error('Cloud is not configured.');await cloud().signOut()}catch(e){cloudMsg(e.message)}};$('#cloud-create-household').onclick=async()=>{try{if(!cloud()?.configured)throw Error('Configure Supabase first.');const id=await cloud().createHousehold($('#cloud-household-name').value.trim());cloudMsg('Household created and connected: '+id)}catch(e){cloudMsg(e.message)}};$('#cloud-join-household').onclick=async()=>{try{if(!cloud()?.configured)throw Error('Configure Supabase first.');const token=$('#cloud-invite-token').value.trim();if(!token)throw Error('Paste the invitation code.');await cloud().redeemInvitation(token);cloudMsg('Invitation accepted. Household sharing connected.')}catch(e){cloudMsg(e.message)}};$('#cloud-create-invite').onclick=async()=>{try{if(!cloud()?.configured||!cloud().householdId)throw Error('Sign in and create/join a household first.');const inv=await cloud().createInvitation(cloud().householdId,72,1);const share='Northstar Family Edition invitation\nCode: '+inv.token+'\nExpires: '+inv.expires_at+'\nOpen your Northstar site, sign in, then paste the code in Settings → Family sharing.';$('#cloud-invite-output').value=share;cloudMsg('Invitation created. Share the code privately.')}catch(e){cloudMsg(e.message)}};$('#cloud-copy-invite').onclick=async()=>{try{const value=$('#cloud-invite-output').value;if(!value)throw Error('Create an invitation first.');await navigator.clipboard.writeText(value);cloudMsg('Invitation details copied.')}catch(e){cloudMsg(e.message)}};$('#backup-export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='northstar-family-backup.json';a.click();URL.revokeObjectURL(a.href);$('#settings-msg').textContent='Backup download started.'};$('#backup-import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const d=JSON.parse(await f.text());if(!d||!Array.isArray(d.meals)||!Array.isArray(d.shopping))throw Error('This does not look like a Northstar backup.');const importedRecipes=Array.isArray(d.recipes)?d.recipes:[];const custom=importedRecipes.filter(r=>r&&r.name&&Number(r.id)>300&&!defaults.recipes.some(n=>n.name===r.name));data={...defaults,...d,recipes:[...defaults.recipes,...custom],modules:{...defaults.modules,...d.modules}};save();render()}catch(err){$('#settings-msg').textContent='Import failed: '+err.message}};$('#reset-data').onclick=()=>{if(confirm('Delete all Northstar Family Edition data saved in this browser? This cannot be undone.')){data=structuredClone(defaults);save();render()}};return}
}

window.addEventListener('northstar:get-state',e=>{if(e.detail&&typeof e.detail.set==='function')e.detail.set(data)});
window.addEventListener('northstar:apply-remote',e=>{const incoming=e.detail&&e.detail.data;if(!incoming)return;if(typeof incoming.household==='string')data.household=incoming.household;if(Array.isArray(incoming.recipes))data.recipes=incoming.recipes;for(const k of ['meals','shopping','chores','events','notices'])if(Array.isArray(incoming[k]))data[k]=incoming[k];save();render()});

shell();save();
})();